  ('Sabiha Gökçen 1935''te planör eğitimi için hangi ülkeye gönderildi?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Tosun Paşa''da Tellioğulları ve Seferoğulları''nın paylaşamadığı alanın adı hangisidir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Muhsin Bey''de Ali Nazik İstanbul''a hangi müzik türünde yıldız olmak için gelir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Kelebeğin Rüyası''nın öyküsü hangi Türkiye kentinde geçer?', 'Türkiye yerel kültürü; stil kararı.'),
  ('İstanbul Kanatlarımın Altında''da uçuşuyla öne çıkan tarihî kişi hangisidir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Susuz Yaz''ın uyarladığı aynı adlı öyküyü yazan kişi kimdir?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Geleneksel Karagöz tasvirleri ışığı geçirebilmesi için hangi malzemeden hazırlanır?', 'Türkiye yerel kültürü; stil kararı.'),
  ('Mevlevi semazeninin başındaki uzun keçe başlığın adı hangisidir?', 'Türkiye yerel kültürü; stil kararı.')
  ) v(soru, neden)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Karıştırma (TR + EN aynı permütasyon)
drop table if exists pg_temp._parti_karistir;
create temp table _parti_karistir as
select q.id, array_agg(s.idx order by s.rnd) as perm
  from public.questions q
  cross join lateral (
    select (ordinality - 1)::int as idx, random() as rnd
      from jsonb_array_elements(q.secenekler) with ordinality
  ) s
 where q.created_at >= transaction_timestamp()
 group by q.id;

update public.questions q
   set secenekler = (select jsonb_agg(q.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o)),
       dogru_cevap = (array_position(k.perm, q.dogru_cevap::int) - 1)::smallint
  from _parti_karistir k
 where q.id = k.id;

update public.question_translations t
   set secenekler = (select jsonb_agg(t.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o))
  from _parti_karistir k
 where t.question_id = k.id;

drop table if exists pg_temp._parti_karistir;
